import{_ as a,o as s,c as n,ao as t}from"./chunks/framework.zpOnjbUU.js";const u=JSON.parse('{"title":"Moving between DGGS","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/between_grids.md","filePath":"tutorials/between_grids.md","lastUpdated":null}'),i={name:"tutorials/between_grids.md"};function l(o,e,p,r,c,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="Moving-between-DGGS" tabindex="-1">Moving between DGGS <a class="header-anchor" href="#Moving-between-DGGS" aria-label="Permalink to &quot;Moving between DGGS {#Moving-between-DGGS}&quot;">​</a></h1><p>Move data between grid systems when you need to combine datasets or use a different cell shape. <code>regrid</code> handles both a change of system and a change of resolution.</p><p>This example moves monthly soil moisture from HEALPix to IGeo7. We compare area averaging and point interpolation, first on a much finer destination and then on grids of similar cell size. The setup repeats the data loading from <a href="./regridding">Regridding</a>, so you can run this page on its own.</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ENV[&quot;RASTERDATASOURCES_PATH&quot;] = mkpath(get(ENV, &quot;RASTERDATASOURCES_PATH&quot;, joinpath(tempdir(), &quot;rasterdatasources&quot;)))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import DiscreteGlobalGrids as DGG</span></span>
<span class="line"><span>import DimensionalData as DD</span></span>
<span class="line"><span>using Rasters, RasterDataSources</span></span>
<span class="line"><span>import NCDatasets</span></span>
<span class="line"><span>import Extents</span></span>
<span class="line"><span>using Statistics</span></span>
<span class="line"><span>using GLMakie, GeoMakie</span></span>
<span class="line"><span>using DiscreteGlobalGridsVisualization: dggpoly, dggpoly!</span></span>
<span class="line"><span>GLMakie.activate!(inline = true)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>soil = Rasters.set(Raster(RasterDataSources.getraster(CPCSoil; period = &quot;1981-2010&quot;);</span></span>
<span class="line"><span>    name = :soilw), Ti =&gt; 1:12)</span></span>
<span class="line"><span>soil = DD.rebuild(soil; metadata = DD.NoMetadata())</span></span></code></pre></div><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>healpix = DGG.levelgrid(DGG.HEALPixSystem(), 7)</span></span>
<span class="line"><span>soilonhealpix = DGG.regrid(soil; to = healpix)</span></span></code></pre></div><h2 id="Move-the-cube-from-HEALPix-onto-IGeo7" tabindex="-1">Move the cube from HEALPix onto IGeo7 <a class="header-anchor" href="#Move-the-cube-from-HEALPix-onto-IGeo7" aria-label="Permalink to &quot;Move the cube from HEALPix onto IGeo7 {#Move-the-cube-from-HEALPix-onto-IGeo7}&quot;">​</a></h2><p><code>to</code> names the destination grid and <code>from</code> names the source grid:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>igeo7 = DGG.levelgrid(DGG.IGeo7System(), 5)</span></span>
<span class="line"><span>crossed = DGG.regrid(soilonhealpix; to = igeo7, from = healpix)</span></span></code></pre></div><p>The result has one value per IGeo7 cell for each of the twelve months. Plot January to see the soil moisture field on the new cells; missing ocean values remain blank.</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>january = Rasters.replace_missing(crossed[Ti = 1], NaN)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fig = Figure(size = (820, 400))</span></span>
<span class="line"><span>ax = GeoAxis(fig[1, 1]; dest = &quot;+proj=natearth2&quot;, xticks = -120:60:120,</span></span>
<span class="line"><span>    yticks = -60:30:60, title = &quot;January on IGeo7 level 5&quot;)</span></span>
<span class="line"><span>plt = dggpoly!(ax, january; color = january, colormap = :viridis)</span></span>
<span class="line"><span>Colorbar(fig[1, 2], plt; label = &quot;soil moisture (mm)&quot;)</span></span>
<span class="line"><span>fig</span></span></code></pre></div><h2 id="Check-the-cell-size-and-the-land-mean" tabindex="-1">Check the cell size and the land mean <a class="header-anchor" href="#Check-the-cell-size-and-the-land-mean" aria-label="Permalink to &quot;Check the cell size and the land mean {#Check-the-cell-size-and-the-land-mean}&quot;">​</a></h2><p>Metres across a cell, on either grid:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DGG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cellsize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(healpix), DGG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cellsize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(igeo7)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">(50934.54534963078, 55089.48974970403)</span></span></code></pre></div><p>These levels have similar cell widths. Comparing their plain means gives a quick check of the effect on the data. For an area-weighted comparison, use <code>cell_area</code> weights on IGeo7 and account for changes in coastal coverage; its cells are only approximately equal in area.</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mean(skipmissing(soilonhealpix)), mean(skipmissing(crossed))</span></span></code></pre></div><h2 id="Refine-a-coarse-field-onto-a-finer-grid" tabindex="-1">Refine a coarse field onto a finer grid <a class="header-anchor" href="#Refine-a-coarse-field-onto-a-finer-grid" aria-label="Permalink to &quot;Refine a coarse field onto a finer grid {#Refine-a-coarse-field-onto-a-finer-grid}&quot;">​</a></h2><p>A finer destination makes the choice of method visible. Choose according to what a source value represents: an average over a cell, or a measurement at a point.</p><table tabindex="0"><thead><tr><th style="text-align:right;">method</th><th style="text-align:right;">what a destination cell gets</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Conservative()</code> (default)</td><td style="text-align:right;">the area-weighted mean of the source cells under it</td></tr><tr><td style="text-align:right;"><code>BarycentricPoint()</code></td><td style="text-align:right;">a sample at its centre, interpolated from surrounding source centres</td></tr></tbody></table><p>HEALPix level 4 cells are 407 km across, against 55 km on IGeo7 level 5, so roughly fifty destination cells sit under each source cell:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>coarse = DGG.levelgrid(DGG.HEALPixSystem(), 4)</span></span>
<span class="line"><span>oncoarse = DGG.regrid(soil[Ti = 1]; to = coarse)</span></span></code></pre></div><p>Both methods run across that pair:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>blocky = DGG.regrid(oncoarse; to = igeo7, from = coarse)</span></span>
<span class="line"><span>smooth = DGG.regrid(oncoarse; to = igeo7, from = coarse,</span></span>
<span class="line"><span>    method = DGG.BarycentricPoint())</span></span></code></pre></div><p>Index by an extent to draw Europe alone:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>europe = Extents.Extent(X = (-12.0, 42.0), Y = (35.0, 65.0))</span></span>
<span class="line"><span>crange = extrema(filter(!isnan, january))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fig = Figure(size = (900, 430))</span></span>
<span class="line"><span>plots = map(enumerate((&quot;Conservative()&quot; =&gt; blocky,</span></span>
<span class="line"><span>                       &quot;BarycentricPoint()&quot; =&gt; smooth))) do (k, (name, field))</span></span>
<span class="line"><span>    ax = GeoAxis(fig[1, k]; dest = &quot;+proj=laea +lat_0=52 +lon_0=15&quot;,</span></span>
<span class="line"><span>        xticks = -10:10:40, yticks = 35:10:65, title = name)</span></span>
<span class="line"><span>    sub = Rasters.replace_missing(field, NaN)[DGG.Cells(DGG.Covering(europe))]</span></span>
<span class="line"><span>    dggpoly!(ax, sub; color = sub, colormap = :viridis, colorrange = crange)</span></span>
<span class="line"><span>end</span></span>
<span class="line"><span>Colorbar(fig[1, 3], first(plots); label = &quot;soil moisture (mm)&quot;)</span></span>
<span class="line"><span>fig</span></span></code></pre></div><p><code>Conservative()</code> repeats a source value in destination cells wholly inside that source cell, and combines values where cells overlap. The coarse HEALPix pattern remains visible. <code>BarycentricPoint()</code> treats the values as samples at the source centres and interpolates a smoother surface. Neither method adds measurements at the finer resolution.</p><h2 id="Compare-the-two-methods-at-equal-resolution" tabindex="-1">Compare the two methods at equal resolution <a class="header-anchor" href="#Compare-the-two-methods-at-equal-resolution" aria-label="Permalink to &quot;Compare the two methods at equal resolution {#Compare-the-two-methods-at-equal-resolution}&quot;">​</a></h2><p>HEALPix level 7 and IGeo7 level 5 hold cells of nearly the same size, so each destination cell draws on one source cell and its immediate neighbours. Run <code>BarycentricPoint()</code> across that pair:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pointwise = Rasters.replace_missing(</span></span>
<span class="line"><span>    DGG.regrid(soilonhealpix[Ti = 1]; to = igeo7, from = healpix,</span></span>
<span class="line"><span>        method = DGG.BarycentricPoint()), NaN)</span></span></code></pre></div><p>The 99th percentile of the absolute difference, beside the standard deviation of the field itself, in millimetres:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>q99 = quantile(abs.(filter(!isnan, january .- pointwise)), 0.99)</span></span>
<span class="line"><span>(q99 = q99, sigma = std(filter(!isnan, january)))</span></span></code></pre></div><p>Compare <code>q99</code> with <code>sigma</code> to judge the method difference relative to the field&#39;s own variation. The third panel shows where the methods differ:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>conservative = january[DGG.Cells(DGG.Covering(europe))]</span></span>
<span class="line"><span>barycentric = pointwise[DGG.Cells(DGG.Covering(europe))]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fig = Figure(size = (1240, 430))</span></span>
<span class="line"><span>plots = map(enumerate((&quot;Conservative()&quot; =&gt; conservative,</span></span>
<span class="line"><span>                       &quot;BarycentricPoint()&quot; =&gt; barycentric))) do (k, (name, field))</span></span>
<span class="line"><span>    ax = GeoAxis(fig[1, k]; dest = &quot;+proj=laea +lat_0=52 +lon_0=15&quot;,</span></span>
<span class="line"><span>        xticks = -10:10:40, yticks = 35:10:65, title = name)</span></span>
<span class="line"><span>    dggpoly!(ax, field; color = field, colormap = :viridis, colorrange = crange)</span></span>
<span class="line"><span>end</span></span>
<span class="line"><span>Colorbar(fig[1, 3], first(plots); label = &quot;soil moisture (mm)&quot;)</span></span>
<span class="line"><span>ax = GeoAxis(fig[1, 4]; dest = &quot;+proj=laea +lat_0=52 +lon_0=15&quot;,</span></span>
<span class="line"><span>    xticks = -10:10:40, yticks = 35:10:65, title = &quot;difference&quot;)</span></span>
<span class="line"><span>plt = dggpoly!(ax, conservative; color = conservative .- barycentric,</span></span>
<span class="line"><span>    colormap = :balance, colorrange = (-q99, q99))</span></span>
<span class="line"><span>Colorbar(fig[1, 5], plt; label = &quot;Conservative() − BarycentricPoint() (mm)&quot;)</span></span>
<span class="line"><span>fig</span></span></code></pre></div><p>Coastal cells are particularly sensitive to the method: area averaging uses overlap weights, while point interpolation uses surrounding sample sites. Missing source values can therefore affect different destination cells. Compare how many cells each method leaves missing:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>count(isnan, pointwise) - count(isnan, january)</span></span></code></pre></div><h2 id="Reuse-one-plan-across-the-twelve-months" tabindex="-1">Reuse one plan across the twelve months <a class="header-anchor" href="#Reuse-one-plan-across-the-twelve-months" aria-label="Permalink to &quot;Reuse one plan across the twelve months {#Reuse-one-plan-across-the-twelve-months}&quot;">​</a></h2><p><code>plan_regrid</code> builds the weights for the pair of grids once. Every field that crosses the same pair — the twelve months here — reuses them:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plan = DGG.plan_regrid(soilonhealpix; to = igeo7, from = healpix)</span></span></code></pre></div><p>Reuse the output buffer while computing a monthly mean. Each call replaces the previous month&#39;s values:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dest = DGG.regrid(soilonhealpix[Ti = 1], plan)</span></span>
<span class="line"><span>seasonal = map(1:12) do m</span></span>
<span class="line"><span>    DGG.regrid!(dest, soilonhealpix[Ti = m], plan)</span></span>
<span class="line"><span>    mean(skipmissing(dest))</span></span>
<span class="line"><span>end</span></span></code></pre></div><p>Plot the monthly cell means to see the seasonal cycle:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fig = Figure(size = (600, 340))</span></span>
<span class="line"><span>ax = Axis(fig[1, 1]; xticks = 1:12, xlabel = &quot;month&quot;,</span></span>
<span class="line"><span>    ylabel = &quot;mean soil moisture (mm)&quot;, title = &quot;global land mean, IGeo7 level 5&quot;)</span></span>
<span class="line"><span>scatterlines!(ax, 1:12, seasonal)</span></span>
<span class="line"><span>fig</span></span></code></pre></div><h2 id="Let-the-destination-match-the-source-resolution" tabindex="-1">Let the destination match the source resolution <a class="header-anchor" href="#Let-the-destination-match-the-source-resolution" aria-label="Permalink to &quot;Let the destination match the source resolution {#Let-the-destination-match-the-source-resolution}&quot;">​</a></h2><p>Pass a system as <code>to</code> to choose the destination level automatically. Here it selects the IGeo7 level closest in cell size to HEALPix level 7:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DGG.regrid(soilonhealpix[Ti = 1]; to = DGG.IGeo7System(), from = healpix)</span></span></code></pre></div><p>For a regional destination, pass a cell collection or coverage as <code>to</code>; <a href="./multiorder">Multi-order coverage</a> shows that workflow. <a href="./../api/regridding-methods">Choosing a regridding method</a> provides the method and missing-data reference.</p><hr><p><em>This page was generated using <a href="https://github.com/fredrikekre/Literate.jl" target="_blank" rel="noreferrer">Literate.jl</a>.</em></p>`,48)])])}const g=a(i,[["render",l]]);export{u as __pageData,g as default};
